// Tudo chega como texto (o app manda formulário simples).
const corpo = $('Recebe pedido do app').first().json.body || {};
const texto = (v) => String(v ?? '').trim();
const ACOES = ['listar', 'preparar', 'emitir', 'conferir'];
const acao = ACOES.includes(texto(corpo.acao)) ? texto(corpo.acao) : '';
const REC = /^rec[A-Za-z0-9]{14}$/;
const clienteId = REC.test(texto(corpo.clienteId)) ? texto(corpo.clienteId) : '';
const localId = REC.test(texto(corpo.localId)) ? texto(corpo.localId) : '';
const notaId = REC.test(texto(corpo.notaId)) ? texto(corpo.notaId) : '';
const descricao = texto(corpo.descricao);
// Aceita 290 / 290,5 / 290,50 / 290.50 / 1.290,50.
let bruto = texto(corpo.valor);
if (bruto.includes(',')) bruto = bruto.replace(/\./g, '').replace(',', '.');
const valor = /^\d{1,9}(\.\d{1,2})?$/.test(bruto) && Number(bruto) > 0 ? Number(bruto).toFixed(2) : '';
const confirmar = texto(corpo.confirmar) === '1';
const confirmarRepetida = texto(corpo.confirmarRepetida) === '1';
let erro = '';
if (!acao) erro = 'Ação inválida.';
else if (acao === 'preparar' || acao === 'emitir') {
  if (!clienteId) erro = 'Escolha o cliente.';
  else if (!descricao) erro = 'Falta a descrição do serviço.';
  else if (descricao.length > 1100) erro = 'A descrição passou de 1100 caracteres.';
  else if (!valor) erro = 'Confira o valor.';
  else if (acao === 'emitir' && !confirmar) erro = 'Falta confirmar a emissão.';
} else if (acao === 'conferir' && !notaId) erro = 'Nota inválida.';
return [{ json: { acao, clienteId, localId, notaId, descricao, valor, confirmarRepetida, erro } }];

const e = $('Le entrada').first().json;
const ler = (no) => $(no).all().map((i) => i.json);
const brutos = { notas: ler('Busca notas'), clientes: ler('Busca clientes'), locais: ler('Busca locais') };
const responder = (resposta) => [{ json: { proximo: 'responder', resposta } }];
// Banco fora do ar não pode parecer "nenhuma nota".
if (Object.values(brutos).some((l) => l.some((j) => j && j.error))) return responder({ ok: false, mensagem: 'Não foi possível falar com o banco agora. Tente de novo em instantes.' });
const so = (l) => l.filter((j) => j && j.id);
const notas = so(brutos.notas), clientes = so(brutos.clientes), locais = so(brutos.locais);

const saude = $('Status do servico').first().json || {};
const AMBIENTES = { restrita: 'Testes', producao: 'Producao' };
// Fase 4 (13/11/2026): o serviço de notas diz quais emissores ele conhece. Serviço antigo (sem a lista)
// só emite pelo CNPJ 1: nota de cliente do CNPJ 2 nunca pode sair por ele.
const servicoTem = (em) => em === 'CNPJ 1' || Boolean(saude.emissores && saude.emissores[em]);
const MSG_SERVICO_VELHO = 'O serviço de notas ainda não conhece o CNPJ 2. Reabra o atalho "Servidor n8n". Nada foi enviado.';
const ambiente = saude.ok === true ? AMBIENTES[saude.ambiente] : undefined;

const nota = (r) => {
  const f = r.fields;
  return { id: r.id, ambiente: f.Ambiente, emissor: f.Emissor || 'CNPJ 1', serie: f.Serie, numeroDps: f.Numero_DPS, status: f.Status, chave: f.Chave_Acesso || '', numeroNota: f.Numero_NFSe || '',
    situacao: f.Situacao || '', clienteId: f.Cliente_Ref || '', tomadorNome: f.Tomador_Nome || '', tomadorDocumento: f.Tomador_Documento || '', obra: f.Obra || '',
    descricao: f.Descricao || '', valor: f.Valor, competencia: f.Competencia || '', erro: f.Erro || '', emitidaEm: f.Emitida_Em || '' };
};

if (e.acao === 'listar') {
  const lista = notas.filter((r) => !e.clienteId || r.fields.Cliente_Ref === e.clienteId).map(nota).sort((a, b) => b.numeroDps - a.numeroDps);
  return responder({ ok: true, ambiente: ambiente || '', notas: lista });
}

if (!ambiente) return responder({ ok: false, servicoFora: true, mensagem: 'O serviço de notas não está ligado. Reabra o atalho "Servidor n8n". Nada foi enviado.' });

if (e.acao === 'conferir') {
  const r = notas.find((n) => n.id === e.notaId);
  if (!r) return responder({ ok: false, mensagem: 'Nota não encontrada.' });
  if (r.fields.Status !== 'Sem resposta' && r.fields.Status !== 'Enviando') return responder({ ok: false, mensagem: 'Esta nota não está aguardando conferência.' });
  if (r.fields.Ambiente !== ambiente) return responder({ ok: false, mensagem: 'Esta nota é de outro ambiente.' });
  const emissorDaNota = r.fields.Emissor || 'CNPJ 1';
  if (!servicoTem(emissorDaNota)) return responder({ ok: false, servicoFora: true, mensagem: MSG_SERVICO_VELHO });
  return [{ json: { proximo: 'conferir', notaId: r.id, numero: r.fields.Numero_DPS, emissor: emissorDaNota } }];
}

// ---- preparar / emitir ----
const semAcento = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase();
const cliente = clientes.find((c) => c.id === e.clienteId);
if (!cliente) return responder({ ok: false, mensagem: 'Cliente não encontrado.' });
const f = cliente.fields;
const emissor = f.Atendido_Por === 'CNPJ 2' ? 'CNPJ 2' : 'CNPJ 1';
if (!servicoTem(emissor)) return responder({ ok: false, servicoFora: true, mensagem: MSG_SERVICO_VELHO });
const problemas = [], avisos = [];
const documento = String(f.CPF_CNPJ || '').replace(/\D/g, '');
if (documento.length !== 11 && documento.length !== 14) problemas.push('O cliente está sem CPF ou CNPJ válido no cadastro.');
const nome = String(f.Razao_Social_Nome || f.Nome_Fantasia_Identificador || '').trim();
if (!nome) problemas.push('O cliente está sem nome no cadastro.');
if (f.Status === 'Inativo') avisos.push('Este cliente está inativo no cadastro.');
if (f.Exigencia_Fiscal === 'Apenas Recibo') avisos.push('No cadastro, este cliente é "Apenas Recibo".');

function endereco(l, rotulo) {
  const bruto = String(l.fields.Endereco_Completo || '');
  const cep = (bruto.match(/CEP\s*(\d{5})-?(\d{3})/i) || []);
  const partes = bruto.split(',').map((p) => p.trim()).filter((p) => p && !/^CEP\b/i.test(p));
  const bc = String(l.fields.Bairro_Cidade || '').match(/^(.*?)\s*\/\s*(.*?)\s*-\s*([A-Za-z]{2})\s*$/) || [];
  const r = { cep: cep[1] ? cep[1] + cep[2] : '', logradouro: partes[0] || '', numero: partes[1] || '', complemento: partes.slice(2).join(', '), bairro: (bc[1] || '').trim(), cidade: (bc[2] || '').trim(), uf: (bc[3] || '').toUpperCase() };
  const faltam = [!r.cep && 'CEP', !r.logradouro && 'rua', !r.numero && 'número', !r.bairro && 'bairro', !r.cidade && 'cidade'].filter(Boolean);
  if (faltam.length) problemas.push(rotulo + ': falta ' + faltam.join(', ') + ' no cadastro.');
  // Nota com outro município muda onde o ISS incide: por enquanto essa fica no portal.
  else if (semAcento(r.cidade) !== 'JOINVILLE' || r.uf !== 'SC') problemas.push(rotulo + ' fora de Joinville: emita esta pelo portal.');
  r.municipioIbge = '4209102';
  r.texto = [r.logradouro, r.numero, r.complemento, r.bairro, r.cidade + ' - ' + r.uf, 'CEP ' + r.cep.slice(0, 5) + '-' + r.cep.slice(5)].filter(Boolean).join(', ');
  return r;
}
const doCliente = locais.filter((l) => (l.fields.Cliente_Vinculado || [])[0] === cliente.id);
const ativos = doCliente.filter((l) => l.fields.Status !== 'Arquivado' && l.fields.Status !== 'Inativo');
const localCnpj = ativos.find((l) => l.fields.Nome_do_Local === 'Endereço do CNPJ') || ativos[0];
let tomadorEnd = null, obraEnd = null;
if (!localCnpj) problemas.push('O cliente não tem endereço no cadastro.');
else {
  tomadorEnd = endereco(localCnpj, 'Endereço do cliente');
  const localObra = e.localId ? doCliente.find((l) => l.id === e.localId) : localCnpj;
  if (!localObra) problemas.push('Esse endereço de obra não é deste cliente.');
  else obraEnd = localObra.id === localCnpj.id ? tomadorEnd : endereco(localObra, 'Endereço da obra');
}

const hoje = new Date(Date.now() - 3 * 3600 * 1000 - 60 * 1000).toISOString().slice(0, 10);
const doMesmoAmbiente = notas.filter((n) => n.fields.Ambiente === ambiente);
const repetida = doMesmoAmbiente.find((n) => (n.fields.Emissor || 'CNPJ 1') === emissor && ['Enviando', 'Emitida', 'Sem resposta'].includes(n.fields.Status)
  && n.fields.Tomador_Documento === documento && Number(n.fields.Valor) === Number(e.valor)
  && n.fields.Descricao === e.descricao && n.fields.Competencia === hoje);

if (e.acao === 'preparar') {
  return responder({ ok: true, ambiente, emissor, problemas, avisos, podeEmitir: problemas.length === 0,
    tomador: { nome, documento, tipo: documento.length === 11 ? 'CPF' : 'CNPJ', endereco: tomadorEnd ? tomadorEnd.texto : '' },
    obra: obraEnd ? obraEnd.texto : '', descricao: e.descricao, valor: e.valor, competencia: hoje,
    repetida: repetida ? nota(repetida) : null });
}

if (problemas.length) return responder({ ok: false, problemas, mensagem: problemas.join(' ') });
if (repetida && !e.confirmarRepetida) return responder({ ok: false, repetida: nota(repetida), mensagem: 'Já existe uma nota igual hoje para este cliente. Nada foi enviado.' });

const serie = Number((saude.emissores && saude.emissores[emissor] && saude.emissores[emissor].serie) || saude.serie);
const usados = notas.filter((n) => n.fields.Ambiente === ambiente && (n.fields.Emissor || 'CNPJ 1') === emissor && n.fields.Serie === serie).map((n) => Number(n.fields.Numero_DPS) || 0);
let numero = Math.max(0, ...usados) + 1;
// No ambiente de testes do governo os números não voltam: os testes apagam as linhas daqui, não as de lá.
if (ambiente === 'Testes') numero = Math.max(numero, Math.floor(Date.now() / 1000));

const limpa = ({ texto, cidade, uf, ...resto }) => resto;
const pedido = {
  numero, emissor, descricao: e.descricao, valor: e.valor, obra: limpa(obraEnd),
  tomador: { [documento.length === 11 ? 'cpf' : 'cnpj']: documento, nome, endereco: limpa(tomadorEnd) },
};
const reserva = { fields: {
  Ambiente: ambiente, Emissor: emissor, Serie: serie, Numero_DPS: numero, Status: 'Enviando', Cliente_Ref: cliente.id, Tomador_Documento: documento, Tomador_Nome: nome,
  Obra: obraEnd.texto, Descricao: e.descricao, Valor: Number(e.valor), Competencia: hoje,
} };
return [{ json: { proximo: 'emitir', pedido, reserva, ambiente } }];

const d = $('Decide').first().json;
const BASE = 'http://127.0.0.1:5690/v0/app6PyYmtFduIMp7B/tblNotasFiscais1/';
const http = $input.first().json || {};
const status = Number(http.statusCode) || 0;
const r = http.body && typeof http.body === 'object' ? http.body : {};
const dadosNota = (x) => ({ Chave_Acesso: x.chaveAcesso, Numero_NFSe: String(x.numeroNota || ''), Situacao: String(x.situacao || ''), Xml_Nota: x.nfseXml || '', Emitida_Em: new Date().toISOString(), Erro: '' });

if (d.proximo === 'conferir') {
  const url = BASE + d.notaId;
  if (status === 200 && r.ok === true && r.existe === true && r.chaveAcesso) {
    return [{ json: { gravar: true, url, corpo: { fields: { Status: 'Emitida', ...dadosNota(r) } },
      resposta: { ok: true, existe: true, notaId: d.notaId, numeroNota: String(r.numeroNota || ''), chave: r.chaveAcesso, situacao: String(r.situacao || ''), mensagem: 'A nota foi emitida.' } } }];
  }
  if (status === 200 && r.ok === true && r.existe === false) {
    return [{ json: { gravar: true, url, corpo: { fields: { Status: 'Recusada', Erro: 'O governo não tem nota com este número.' } },
      resposta: { ok: true, existe: false, notaId: d.notaId, mensagem: 'O governo não tem esta nota: ela não foi emitida. Pode emitir de novo.' } } }];
  }
  return [{ json: { gravar: false, resposta: { ok: false, notaId: d.notaId, mensagem: 'Não deu para consultar o governo agora. Tente conferir de novo em instantes.' } } }];
}

const notaId = $('Reserva numero').first().json.id;
const url = BASE + notaId;
if (status === 201 && r.ok === true && r.chaveAcesso) {
  return [{ json: { gravar: true, url, corpo: { fields: { Status: 'Emitida', Id_DPS: r.idDps || '', ...dadosNota(r) } },
    resposta: { ok: true, ambiente: d.ambiente, nota: { id: notaId, numeroDps: d.pedido.numero, numeroNota: String(r.numeroNota || ''), chave: r.chaveAcesso, situacao: String(r.situacao || ''), valor: d.pedido.valor, alertas: r.alertas || [] } } } }];
}
// 400 = barrado aqui antes de sair do PC; 422 = o governo respondeu e recusou. Nos dois não existe nota.
if (status === 400 || status === 422) {
  const erros = Array.isArray(r.erros) ? r.erros : [];
  const texto = erros.map((x) => [x.codigo, x.descricao, x.complemento].filter(Boolean).join(': ')).join(' | ') || 'Recusada.';
  return [{ json: { gravar: true, url, corpo: { fields: { Status: 'Recusada', Id_DPS: r.idDps || '', Erro: texto.slice(0, 2000) } },
    resposta: { ok: false, recusada: true, notaId, erros, mensagem: 'A nota foi recusada e não foi emitida: ' + texto } } }];
}
// Qualquer outra coisa: a nota pode ter saído. Só uma consulta ao governo diz.
const motivo = (Array.isArray(r.erros) && r.erros[0] && r.erros[0].descricao) || http.message || (http.error && http.error.message) || 'sem resposta';
return [{ json: { gravar: true, url, corpo: { fields: { Status: 'Sem resposta', Id_DPS: r.idDps || '', Erro: String(motivo).slice(0, 2000) } },
  resposta: { ok: false, semResposta: true, notaId, mensagem: 'Não sei se a nota saiu. Não emita de novo: use "conferir" primeiro.' } } }];

const m = $('Monta resultado').first().json;
const resposta = { ...m.resposta };
const salvo = $input.first().json || {};
if (m.gravar && !salvo.id) {
  // O governo já respondeu; só o registro aqui falhou. A chave não pode se perder.
  resposta.avisoRegistro = 'A resposta do governo não foi registrada no sistema. Anote: ' + JSON.stringify({ notaId: resposta.notaId || (resposta.nota && resposta.nota.id), chave: resposta.chave || (resposta.nota && resposta.nota.chave) || '' });
}
return [{ json: resposta }];
